; MemSet &H059A
; HL : Start adress
; BC : Number
; A  : With char
; ----------------------------------------
0000059A:	LD (HL),A		; put val(A) in adress(HL)
0000059B:	LD E,L			; HL -> DE
0000059C:	LD D,H
0000059D:	INC DE			; DE+1
0000059E:	LDIR			; DO (HL)->(DE); HL+1; DE+1; BC-1; UNTIL BC=0
000005A0:	RET
; ----------------------------------------

; Search FOR or GOSUB block on stack (skip 2 words)
; Used by 'RETURN' and 'NEXT'
BAKSTK:
000005A1:	LD HL,0004h     ; Look for "FOR" block with
000005A4:	ADD HL,SP       ; same index as specified in D

; LOKFOR - Look for existing "FOR" block
000005A5:	LD A,(HL)       ; Get block ID
000005A6:	INC HL          ; Point to index address
000005A7:	DEC A           ; Is it a "FOR" token
000005A8:	RET NZ          ; No - exit
000005A9:	LD C,(HL)       ; BC = Address of "FOR" index
000005AA:	INC HL
000005AB:	LD B,(HL)
000005AC:	INC HL          ; Point to sign of STEP
000005AD:	PUSH HL         ; Save pointer to sign
000005AE:	LD H,B          ; HL = address of "FOR" index
000005AF:	LD L,C
000005B0:	LD A,D          ; See if an index was specified
000005B1:	OR E            ; DE = 0 if no index specified
000005B2:	EX DE,HL        ; Specified index into HL
000005B3:	JR Z,+02h       ; Skip if no index given
000005B5:	EX DE,HL        ; Index back into DE
000005B6:	RST 10h         ; Compare index with one given (use DCOMPR)
INDFND:
000005B7:	POP HL          ; Restore pointer to sign
000005B8:	RET Z           ; Return if block found
000005B9:	LD BC,000Fh     ; Offset to next block
000005BC:	ADD HL,BC       ; Point to next block
000005BD:	JR -1Ah         ; Keep on looking

000005BF:	PUSH BC
000005C0:	LD BC,FFF0h
000005C3:	LD HL,(F989h)
000005C6:	ADD HL,BC
000005C7:	POP BC
000005C8:	RET
